  ],
  "claims": [
    {
      "claim": "The most transferable lipophilic-amine reference contexts report absolute or systemic oral bioavailability well above 20%: urapidil 72–78%, diphenhydramine 0.69, donepezil ~100%, imipramine-N-oxide 100%, and tiracizine 0.34.",
      "card_ids": ["C01","C03","C05","C07","C08","C13","C15","C20"]
    },
    {
      "claim": "L2 records from the same high-F contexts are consistent: urapidil 72% delayed-release and >70% in animals, diphenhydramine 0.69 fasted, donepezil ~100%, and imipramine-N-oxide 100%.",
      "card_ids": ["C21","C22","C27","C30","C33"]
    },
    {
      "claim": "L4/L5 records for related tricyclic amines show essentially complete oral absorption and high Caco-2 permeability with low efflux: imipramine Fa 100%, Papp ~10.8×10^-6 cm/s and efflux ratio 1.1; desipramine permeability ~10^-5 cm/s or higher.",
      "card_ids": ["C47","C52","C56","C61","C63","C65","C67","C69"]
    },
    {
      "claim": "L6 hepatic-clearance records show imipramine and desipramine have high intrinsic clearance (e.g., imipramine human microsomal CLint 35.4–51.1 µL/min/mg; desipramine human CLint 9–22), indicating potential first-pass metabolism, but these are reference-molecule mechanistic data and do not by themselves establish F<20% for the query.",
      "card_ids": ["C70","C71","C73","C78","C79","C81"]
    },
    {
      "claim": "The only sub-20% records are species-specific or structurally dissimilar (cat benazeprilat 3.2%, rat FK788 9.6%, moexipril 13–22%) and do not transfer to this lipophilic diamine.",
      "card_ids": ["C24","C25","C32"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C70","C71","C72","C73","C74","C76","C77","C78","C79","C80","C81"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement exists for the query molecule.",
    "No matched oral versus intravenous exposure data are available for the query.",
    "L6 hepatic-clearance records are for imipramine and desipramine, not the query; query-specific CLint, protein binding, and free fraction are unknown.",
    "No query-specific permeability, solubility, or gut-wall metabolism data exist; structural analogy to imipramine/desipramine is qualitative.",
    "The exact first-pass metabolic pathways and CYP contributions for the query are not experimentally confirmed."
  ],
  "decision_summary": "Predicted high because the most transferable lipophilic-amine reference contexts consistently report F above 20%, L2 records reinforce this, L3 shows measurable oral exposure, and L4/L5 show high absorption and permeability with low efflux for related amines. L6 high hepatic clearance for imipramine/desipramine is a mechanistic concern that weakens but does not overturn the decision; no affirmative evidence establishes F<20% for the query, so unresolved uncertainty is expressed as low confidence."
}

